"""Build scoped extraction evidence, including every complete source choice."""
import importlib.util,json
from pathlib import Path
H=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('generator',H.with_suffix('.py'));g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
source=json.loads((H/'source.json').read_text());basis=source['basis']
def save(name,x):(H/name).write_text(json.dumps(x,indent=2)+'\n')
recipes={
'q-107293':['5(3x+b)^4: omit inner slope','3(3x+b)^5: inner slope times unchanged outer power','20(3x+b)^4: observed fixed coefficient 20; mechanism unresolved','9(3x+b)^4: observed fixed coefficient 9; mechanism unresolved','15(3x+b)^4: chain rule'],
'q-71954':['32(16x+b)^3: double inner x coefficient','16(8x+b)^3: half outer coefficient','16(16x+b)^3: half outer coefficient and double inner x coefficient','8(8x+b)^3: quarter outer coefficient','32(8x+b)^3: chain rule'],
'q-71956':['-15(b+5x)^2: reverse inner sign','-15(b-5x)^3: leave outer exponent unchanged','15(b+5x)^2: reverse inner and outer signs','15(b-5x)^2: reverse outer sign','-15(b-5x)^2: chain rule'],
'q-342804':['20(4x+b)^4: full derivative'],
'q-342875':['5x^4-4cx^3: inner derivative fragment'],
'q-342883':['5/(2 sqrt(5x+b)): full derivative'],
'q-342891':['x-4x^3: negative half inner derivative; denominator stays outside blank']}
families={'q-107293':'affine-power-radio','q-71954':'affine-power-radio','q-71956':'affine-power-radio','q-342804':'affine-power-blank','q-342875':'polynomial-square-inner-fragment','q-342883':'affine-square-root-full-blank','q-342891':'quartic-reciprocal-root-numerator-fragment'}
classification={'basis':basis,'lineage':source['lineage'],'knowledgePoint':g.KP_ID,'levels':{'easy':{'supported':False,'field_types':[],'template_count':0,'reason':'No complete rated easy source. The two unrated questions lack worked solutions and canonical correct facts; their difficulty cannot be inferred safely.'},'moderate':{'supported':True,'field_types':['radio','blank'],'template_count':2,'radio_choice_bank_profiles':3,'source_ids':['q-107293','q-71954','q-71956','q-342804']},'hard':{'supported':True,'field_types':['blank'],'template_count':3,'source_ids':['q-342875','q-342883','q-342891']}},'templates':[{'id':t,'plot_rating':'none','source_ids':[m for m in families if families[m]==t]} for t in sorted(set(families.values()))],'excluded_sources':[{'id':m,'db_id':g.SOURCES[m][':db/id'],'missing':['difficulty','worked-solution','correct'],'preserved':True} for m in ['q-11414','q-48850']],'canonical_example':'e-183 supports reciprocal-root method; excluded from practice inventory','plots':{'references':[],'new_assets':False,'rating':'none'}}
save('classification.json',classification)
sections=[f'# Template extraction: KP {g.KP_ID}\n\nCaptured basis {basis}, lineage {source["lineage"]}. All source facts are preserved in source.json and reference/source.edn.\n\nThe moderate templates differentiate a fixed power of an affine expression, as a full radio choice or full blank. Hard templates require an inner derivative fragment of a polynomial square, a full affine radical derivative, or a numerator fragment of a reciprocal quartic radical. Keep these answer shapes separate. All use the original fixed two-stage chain-rule solution. No plots or assets occur.\n\nSampling is intentionally narrow: only the affine shift b or specified polynomial c varies. Slopes, exponents and observed complete distractor coefficients stay fixed. In particular the unexplained 20 and 9 in q-107293 are preserved fixed patterns, not assigned an invented learner misconception. No mixed banks are used. Seed and choice order do not define a new mathematical task.\n\nSource wording uses f(g(x)) loosely as outer-function notation and q-342891 uses dy/dx in the response line while its prompt names f. These notational imprecisions are retained for fidelity; the generator and independent verification use the unambiguous displayed f(x).']
components=[]
for m,p in g.DEFAULTS.items():
 q=g.SOURCES[m];f=q[':question/answer-fields'][0];level=q[':question/difficulty'][':db/ident'].split('/')[-1]
 rows=[]
 for a,recipe in zip(f[':answer-field/choices'],recipes[m]):
  rows.append({'source_answer_id':a[':answer/id'],'source_field_id':f[':answer-field/id'],'field_key':f[':answer-field/key'],'profile':m+'-bank' if len(recipes[m])>1 else 'blank','exact_value':a[':answer/value'],'correct':a[':answer/id']==f[':answer-field/correct'][':answer/id'],'parameterized_recipe':recipe,'complete_value_at_original_parameters':True})
 components.append({'source_id':m,'source_db_id':q[':db/id'],'difficulty':level,'template':families[m],'original_parameters':p,'proposed_parameter_values':g.parameters_for(m),'original_prompt':q[':question/problem'],'original_solution':q[':question/worked-solution'],'field_type':f[':answer-field/type'][':db/ident'],'field_key':f[':answer-field/key'],'choices':rows,'transformation': 'See transform() in generator; substitutions act only on affine shifts, c*x^4 with derivative 4*c*x^3, or additive quartic constant. Outer exponents and field layout remain fixed.'})
 sections.append('## '+m+' ('+level+', '+families[m]+')\n\nOriginal parameters: '+json.dumps(p)+'. Proposed values: '+json.dumps(g.parameters_for(m))+'.\n\n'+q[':question/problem']+'\n\nField '+f[':answer-field/key']+' ('+f[':answer-field/type'][':db/ident']+').\n\n'+'\n'.join('- '+r['exact_value']+' → '+r['parameterized_recipe']+(' (correct)' if r['correct'] else '') for r in rows)+'\n\nOriginal fixed solution:\n\n'+q[':question/worked-solution'])
sections.append('## Constraints, identity and validation\n\nAll parameters are integers. Affine shifts b range from -9 through 9; the constant-first negative-slope profile uses b=1 through 9. Polynomial c ranges from 1 through 12. For sqrt(5x+b), the derivative exists only on 5x+b>0. For the reciprocal radical, 2x^4-x^2+c = 2(x^2-1/4)^2+c-1/8 is strictly positive for every real x. Polynomial templates have real domain. Invalid duplicate or equivalent options cause validation failure.\n\nMathematical fingerprints parse the visible function and requested response shape, independent of seed, UUID and option order. They merge identical tasks across radio/blank banks. Field-owned answer identities are deterministic UUIDs. Every source bank is replayed exactly, and every finite parameter value is validated by independent displayed-expression differentiation, unique correct option checks, solution simplification and actual application grading. Generated output has no Math Academy IDs.\n\nReplenishment rechecks native inventory and distinct validated availability under api.lock, prepares additive forms using the configured application contributor, requests native specs, previews, saves exact guarded requests, commits and verifies the full scoped readback. Only this KP and new content entities may change.')
(H/'template-extraction.md').write_text('\n\n'.join(sections)+'\n');save('template-components.json',components)
limits={l:len(g.batch(l,1000)) for l in g.SUPPORTED_LEVELS}
save('capabilities.json',{'version':g.VERSION,'supported_levels':list(g.SUPPORTED_LEVELS),'finite_distinct_tasks':limits,'exceptions':[{'level':'easy','kind':'unsupported','reason':'No complete rated easy practice source; unrated records are missing worked solution and correct answer. No easy questions generated or counted.','nominal_reserve_shortage':5},{'levels':list(g.SUPPORTED_LEVELS),'kind':'finite-limit','reason':'Bounded source-faithful numerical slices; outside these ranges no capability claimed. New source evidence reopens classification.','limits':limits}],'domains':{'q-342883':'5x+b>0','q-342891':'real x; 2(x^2-1/4)^2+c-1/8>0'},'plot_requirements':'none'})
print('Wrote classification, all source components, extraction and capabilities',limits)
